/**
 * Frozen rule snapshot stored in commission_records.rule_snapshot.
 * Structure matches what handle_booking_complete_commission() writes.
 */
export interface CommissionRuleSnapshot {
  rule_id: string | null
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number | null
  priority?: number
  effective_from?: string
  matched_by: 'service_specific' | 'catch_all' | 'artist_default' | 'none'
  recalculated_at?: string
}

// ============================================================
// Sprint 9 — AI Design Assistant: union types + row types
// ============================================================

/** Tattoo style categories for ai_design_requests + ai_design_templates */
export type AiStyleCategory =
  | 'blackwork'
  | 'watercolor'
  | 'traditional'
  | 'neo_trad'
  | 'realism'
  | 'geometric'
  | 'minimalist'
  | 'japanese'
  | 'tribal'
  | 'trash_polka'
  | 'dotwork'
  | 'illustrative'
  | 'abstract'
  | 'lettering'
  | 'other'

/** Status lifecycle for ai_design_requests */
export type AiRequestStatus =
  | 'pending'
  | 'processing'
  | 'completed'
  | 'failed'
  | 'cancelled'

/** Status lifecycle for ai_design_outputs */
export type AiOutputStatus =
  | 'pending'
  | 'generating'
  | 'completed'
  | 'failed'
  | 'rejected'
  | 'approved'

/** AI API providers tracked in ai_usage_log */
export type AiApiProvider =
  | 'anthropic'
  | 'openai'
  | 'stability'
  | 'replicate'
  | 'other'

/** Row type for ai_design_requests */
export type AiDesignRequest =
  Database['public']['Tables']['ai_design_requests']['Row']

/** Insert type for ai_design_requests */
export type AiDesignRequestInsert =
  Database['public']['Tables']['ai_design_requests']['Insert']

/** Update type for ai_design_requests */
export type AiDesignRequestUpdate =
  Database['public']['Tables']['ai_design_requests']['Update']

/** Row type for ai_design_outputs */
export type AiDesignOutput =
  Database['public']['Tables']['ai_design_outputs']['Row']

/** Insert type for ai_design_outputs */
export type AiDesignOutputInsert =
  Database['public']['Tables']['ai_design_outputs']['Insert']

/** Update type for ai_design_outputs */
export type AiDesignOutputUpdate =
  Database['public']['Tables']['ai_design_outputs']['Update']

/** Row type for ai_design_templates */
export type AiDesignTemplate =
  Database['public']['Tables']['ai_design_templates']['Row']

/** Insert type for ai_design_templates */
export type AiDesignTemplateInsert =
  Database['public']['Tables']['ai_design_templates']['Insert']

/** Row type for ai_usage_log */
export type AiUsageLog =
  Database['public']['Tables']['ai_usage_log']['Row']

/** Insert type for ai_usage_log */
export type AiUsageLogInsert =
  Database['public']['Tables']['ai_usage_log']['Insert']

/**
 * Gallery item returned by get_ai_design_gallery().
 * One entry per request, with nested outputs array.
 */
export interface AiDesignGalleryItem {
  request: AiDesignRequest
  outputs: AiDesignOutput[]
}

/**
 * Shape returned by get_ai_studio_usage() and admin_get_ai_platform_usage().
 */
export interface AiUsageSummary {
  total_requests: number
  total_outputs: number
  total_tokens: number
  total_cost_cents: number
  by_model: Record<string, { tokens: number; cost_cents: number; calls: number }>
  by_style: Record<string, { requests: number; outputs: number }>
  daily_breakdown: Array<{
    date: string
    requests: number
    outputs: number
    tokens: number
    cost_cents: number
  }>
}

/** Extended shape from admin_get_ai_platform_usage() */
export interface AiPlatformUsageSummary extends AiUsageSummary {
  total_studios_active: number
  by_provider: Record<string, { tokens: number; cost_cents: number; calls: number }>
  top_studios: Array<{
    studio_id: string
    name: string
    requests: number
    cost_cents: number
  }>
}

